initJs:
function(container, apiUrl, tables) {
    // 売上データ収集ボタン
    const collectSalesBtn = container.querySelector('#collectSalesBtn');
    if (collectSalesBtn) {
        collectSalesBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const salesData = await collectSalesData(startDate, endDate);
                const tbody = container.querySelector('#salesDataTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    salesData.forEach(item => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = item.date;
                        row.insertCell(1).textContent = item.productId;
                        row.insertCell(2).textContent = item.quantity;
                        row.insertCell(3).textContent = item.amount;
                    });
                }
                window.aivicNotify.success('売上データを収集しました');
            } catch (error) {
                window.aivicNotify.error('売上データの収集に失敗しました: ' + error.message);
            }
        });
    }

    // 商品別分析ボタン
    const analyzeByProductBtn = container.querySelector('#analyzeByProductBtn');
    if (analyzeByProductBtn) {
        analyzeByProductBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const salesData = await collectSalesData(startDate, endDate);
                const classifiedData = classifySalesDataByProduct(salesData);
                const validData = filterValidProductData(classifiedData);

                const tbody = container.querySelector('#productAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(validData).forEach(([productId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = productId;
                        row.insertCell(1).textContent = data.totalQuantity;
                        row.insertCell(2).textContent = data.totalAmount;
                        row.insertCell(3).textContent = data.averageDaily;
                    });
                }
                window.aivicNotify.success('商品別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('商品別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 店舗別分析ボタン
    const analyzeByStoreBtn = container.querySelector('#analyzeByStoreBtn');
    if (analyzeByStoreBtn) {
        analyzeByStoreBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const salesData = await collectSalesData(startDate, endDate);
                const classifiedData = classifySalesDataByStore(salesData);

                const tbody = container.querySelector('#storeAnalysisTable tbody');
                if (tbody) {
                    tbody.innerHTML = '';
                    Object.entries(classifiedData).forEach(([storeId, data]) => {
                        const row = tbody.insertRow();
                        row.insertCell(0).textContent = storeId;
                        row.insertCell(1).textContent = data.totalQuantity;
                        row.insertCell(2).textContent = data.totalAmount;
                        row.insertCell(3).textContent = data.averageDaily;
                    });
                }
                window.aivicNotify.success('店舗別分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('店舗別分析に失敗しました: ' + error.message);
            }
        });
    }

    // 相関分析ボタン
    const correlationAnalysisBtn = container.querySelector('#correlationAnalysisBtn');
    if (correlationAnalysisBtn) {
        correlationAnalysisBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const salesData = await collectSalesData(startDate, endDate);
                const weatherData = await collectWeatherData(startDate, endDate);
                const eventData = await collectEventData(startDate, endDate);
                const seasonalData = await collectSeasonalData(startDate, endDate);

                const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
                const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
                const seasonalCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

                const resultDiv = container.querySelector('#correlationResults');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <h4>相関分析結果</h4>
                        <p>天候との相関: ${weatherCorrelation.coefficient}</p>
                        <p>イベントとの相関: ${eventCorrelation.coefficient}</p>
                        <p>季節との相関: ${seasonalCorrelation.coefficient}</p>
                    `;
                }
                window.aivicNotify.success('相関分析を完了しました');
            } catch (error) {
                window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 履歴比較ボタン
    const historicalComparisonBtn = container.querySelector('#historicalComparisonBtn');
    if (historicalComparisonBtn) {
        historicalComparisonBtn.addEventListener('click', async () => {
            try {
                const startDate = container.querySelector('#startDate')?.value;
                const endDate = container.querySelector('#endDate')?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const isValidPeriod = validateComparisonPeriod(startDate, endDate);
                if (!isValidPeriod) {
                    window.aivicNotify.error('比較期間が無効です');
                    return;
                }

                const currentData = await collectSalesData(startDate, endDate);
                let comparisonResult = compareWithHistoricalData(currentData, startDate, endDate);

                if (!comparisonResult.success) {
                    comparisonResult = findAlternativeComparisonData(currentData, startDate, endDate);
                }

                const resultDiv = container.querySelector('#comparisonResults');
                if (resultDiv) {
                    resultDiv.innerHTML = `
                        <h4>履歴比較結果</h4>
                        <p>比較期間: ${comparisonResult.comparisonPeriod}</p>
                        <p>売上変化率: ${comparisonResult.changeRate}%</p>
                        <p>トレンド: ${comparisonResult.trend}</p>
                    `;
                }
                window.aivicNotify.success('履歴比較を完了しました');
            } catch (error) {
                window.aivicNotify.error('履歴比較に失敗しました: ' + error.message);
            }
        });
    }

    // 初期データ読み込み
    const loadInitialData = async () => {
        try {
            const today = new Date();
            const lastWeek = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);

            const startDateInput = container.querySelector('#startDate');
            const endDateInput = container.querySelector('#endDate');

            if (startDateInput) startDateInput.value = lastWeek.toISOString().split('T')[0];
            if (endDateInput) endDateInput.value = today.toISOString().split('T')[0];

        } catch (error) {
            window.aivicNotify.error('初期データの読み込みに失敗しました: ' + error.message);
        }
    };

    loadInitialData();
}
